def compute(vars):
    value_2018 = vars["v1"]
    value_2019 = vars["v2"]
    total = value_2018 + value_2019
    count = 2
    average = total / count

    return {
        "value": average,
        "trace": {
            "value_2018": value_2018,
            "value_2019": value_2019,
            "total": total,
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
